const fs = require('fs');
const src = fs.readFileSync('out/html/core.js','utf8');
const start = src.indexOf('window.game=');
let i = start + 'window.game='.length;
// find matching brace for JSON object
if (src[i] !== '{') throw new Error('expected {');
let depth = 0, inStr = false, esc = false;
for (; i < src.length; i++) {
  const c = src[i];
  if (inStr) {
    if (esc) esc = false;
    else if (c === '\\') esc = true;
    else if (c === '"') inStr = false;
    continue;
  }
  if (c === '"') { inStr = true; continue; }
  if (c === '{') depth++;
  else if (c === '}') {
    depth--;
    if (depth === 0) { i++; break; }
  }
}
const json = src.slice(start + 'window.game='.length, i);
const outer = JSON.parse(json);
const game = JSON.parse(outer.compiled);
const pe = game.scenes['post_event'];
console.log(JSON.stringify(pe.goTo, null, 2));
