on-arrival: {!
Q.has_event = 0;
var choices = this._compileChoices(this.game.scenes['post_event.events_choice']);
if (choices) {
    var rootId = this.state.rootSceneId;
    for (var ci = 0; ci < choices.length; ci++) {
        var ch = choices[ci];
        if (ch.canChoose && ch.id !== rootId) {
            Q.has_event = 1;
            break;
        }
    }
}
